-- SOURCE-FRESH: SCM_MGR 화면 DMF0082 객체·META (DB=ZIOUI1 SERVER_HOST=localhost) FETCHED=2026-11-19 18:08:07
/* 00_PRECHECK_CLOUD — 읽기 전용(변경 없음). 결과를 보고 진행
 * 패키지 DMF0082_CLOUD_DB_MOD_20261119_1808 · 생성 tools/CloudPkg/cloud_pkg.py 1.4.1 · 2026-11-19 18:08
 * 실행 계정 = SCM_MGR (전체 F5 · 반복 실행 안전)
 */
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED

/* 1) 화면 소유 객체 — 클라우드 현재 상태 (CLOUD_STATUS 빈칸 = 클라우드에 없음 → 이 패키지가 생성) */
SELECT E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, O.STATUS AS CLOUD_STATUS, TO_CHAR(O.LAST_DDL_TIME, 'YYYY-MM-DD HH24:MI') AS CLOUD_LAST_DDL
  FROM (SELECT 'GT_DMF0082_ADMIN_GROUP_MEASURE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_CAL_MONTH_END_DATE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_CAL_WEEK_END_DATE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_N_PRICE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_PRICE_BUCKET' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_PRICE_DAILY' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_PRICE_EXCEL' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_PRICE_UNPIVOT' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_FCST_PRICE_WEEKLY' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_MF_SP' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_MST_ITEM_SINGLE_A_V' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_MST_ITEM_SINGLE_B_V' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_MST_ITEM_SINGLE_ORI_V' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_MST_ITEM_SINGLE_V' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_PARAM_TOKEN' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_PJT' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_SAVE_FLAG' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_SELECT_MEASURE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_SITE_ITEM' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_SP_FILTER' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_ADMIN_GROUP_MEASURE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_FCST_N_PRICE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_INTO_GROUP_MEASURE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_SELECT_MEASURE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_SITE_ITEM' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_SITE_ITEM_ALL' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_SITE_ITEM_ALL_V2' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_TEMP_SITE_ITEM_V2' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_FCST' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_FCST_C' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_PRICE' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_PRICE_C' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_VERSION' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_WS_FCST' N, 'TABLE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082' N, 'PACKAGE BODY' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104' N, 'PACKAGE BODY' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104A' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104A' N, 'PACKAGE BODY' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104B' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104B' N, 'PACKAGE BODY' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104C' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082_1104C' N, 'PACKAGE BODY' T FROM DUAL) E
  LEFT JOIN USER_OBJECTS O ON O.OBJECT_NAME = E.N AND O.OBJECT_TYPE = E.T
 ORDER BY 1, 2;

/* 2) 공용 참조 객체(이 패키지가 만들지 않음) — 0건이어야 정상. 행 = 클라우드에 없거나 INVALID → 먼저 이관 필요 */
SELECT E.O AS OWNER, E.N AS OBJECT_NAME, E.T AS OBJECT_TYPE, NVL(MAX(A.STATUS), '없음') AS CLOUD_STATUS
  FROM (SELECT 'SCM_MGR' O, 'FN_GET_DEPT_LIST' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_GET_MULTI_OWNER_NAME' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_MULTY_TIME' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_NEXT_DAY' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_STRING_SPLIT' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PKG_DMF0020' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_ANL_SALES_PLAN_AMT_CREATE_LOCAL_KRW_MKT_FCST_SAVE' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_MKT_FCST_QTY_BALANCE_CREATE' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_SYS_LOG_BATCH' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_SCM_SYS_LOG_BATCH' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_ITEM_M_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_BOM_ENG_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SCM_MST_ITEM_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_DM_PLN_CFM_MKT_DEMAND_PLAN_H' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_DM_PLN_CFM_SELLING_PRICE_H' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_DM_PLN_MKT_FCST_H' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'SEQ1_SCM_MST_FUTURE_PRICE_H' N, 'SEQUENCE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'UF_FX_STRING_SPLIT' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'UF_FX_STRING_SPLITFORIN' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'XIF_GSC_MOVE_EXCHANGE_RATE_SN' N, 'SYNONYM' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'DMF0020_SAVE_SCM_MST_FUTURE_PRICE_ALL' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'FN_GET_DIVISION_YN' N, 'FUNCTION' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PKG_DMF0003' N, 'PACKAGE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_DM_PLN_MKT_FCST_SALES_RESULT_MAPPING' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_SCM_MST_EXCHANGE_RATE' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'PR_SCM_MST_EXCHANGE_RATE_UI' N, 'PROCEDURE' T FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'STRING_SPLIT' N, 'FUNCTION' T FROM DUAL) E
  LEFT JOIN ALL_OBJECTS A ON A.OWNER = E.O AND A.OBJECT_NAME = E.N AND A.OBJECT_TYPE IN (E.T, E.T || ' BODY')
 GROUP BY E.O, E.N, E.T
HAVING NVL(MAX(A.STATUS), '없음') <> 'VALID' OR MIN(A.STATUS) <> 'VALID'
 ORDER BY 1, 2;

/* 3) 참조 테이블·뷰 컬럼 누락 — 0건이어야 정상. 행 = 클라우드 표에 그 컬럼 없음 → PKG 컴파일 ORA-00904 원인.
 *    데이터·PK·배치 영향이 있어 자동 변경 안 함 — 결과를 그대로 전달(예: 2026-10-30 QA SCP_RPT_GLOBAL_PSI_MD_WW.PLAN_TYPE) */
