    UNION ALL SELECT 'SCM_MGR' O, 'TB_FX_USER' T, 'ATTRIBUTE10' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'TB_FX_USER' T, 'XLS_PASSWD' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'TB_FX_USER' T, 'XLS_PASSWD_CHANGE_DATE' C FROM DUAL
    UNION ALL SELECT 'SCM_MGR' O, 'TB_FX_USER' T, 'PERMANENTYN' C FROM DUAL) E
 WHERE NOT EXISTS (SELECT 1 FROM ALL_TABLES X WHERE X.OWNER = E.O AND X.TABLE_NAME = E.T)
   AND NOT EXISTS (SELECT 1 FROM ALL_VIEWS V WHERE V.OWNER = E.O AND V.VIEW_NAME = E.T)
   AND NOT EXISTS (SELECT 1 FROM ALL_SYNONYMS S WHERE S.OWNER = E.O AND S.SYNONYM_NAME = E.T)
 ORDER BY 1, 2;

/* 5) 상위 메뉴 존재 — 1건이어야 정상 */
SELECT MNU_ID, USE_YN FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID = 'Demand_Plan';

/* 6) META 현재 건수 (참고) */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS CLOUD_ROWS, 1 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_MNU_M WHERE MNU_ID = 'DMF0082';
SELECT 'SCM_ADM_API_M' AS TBL, '화면 전용 API' AS AREA, COUNT(*) AS CLOUD_ROWS, 19 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID LIKE 'DMF0082' || '\_%' ESCAPE '\';
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS CLOUD_ROWS, 1 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN (SELECT API_ID FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID = 'DMF0082') AND API_ID NOT LIKE 'DMF0082' || '\_%' ESCAPE '\';
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS CLOUD_ROWS, 26 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID = 'DMF0082';
SELECT 'SCM_ADM_PROC_M' AS TBL, '화면 PKG 프로시저 파라미터' AS AREA, COUNT(*) AS CLOUD_ROWS, 131 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM LIKE 'PKG\_' || 'DMF0082' || '.%' ESCAPE '\';
SELECT 'SCM_ADM_PROC_M' AS TBL, '공용 프로시저 파라미터' AS AREA, COUNT(*) AS CLOUD_ROWS, 39 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM IN (SELECT A.API_URL FROM SCM_MGR.SCM_ADM_API_M A JOIN SCM_MGR.SCM_ADM_MNU_BTN_MPG_M B ON B.API_ID = A.API_ID WHERE B.MNU_ID = 'DMF0082') AND PROC_NM NOT LIKE 'PKG\_' || 'DMF0082' || '.%' ESCAPE '\';
SELECT 'SCM_ADM_USER_GR_MNU_MPG_M' AS TBL, '그룹 메뉴 권한' AS AREA, COUNT(*) AS CLOUD_ROWS, 16 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID = 'DMF0082';
SELECT 'SCM_ADM_USER_GR_MNU_BTN_MPG_M' AS TBL, '그룹 버튼 권한' AS AREA, COUNT(*) AS CLOUD_ROWS, 406 AS CORP_ROWS FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID = 'DMF0082';
SELECT 'SCM_MST_SHEET_COLUMNS' AS TBL, '시트 컬럼' AS AREA, COUNT(*) AS CLOUD_ROWS, 109 AS CORP_ROWS FROM SCM_MGR.SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID = 'DMF0082';
SELECT 'SCM_MST_SHEET_MEASURE' AS TBL, '시트 Measure' AS AREA, COUNT(*) AS CLOUD_ROWS, 26 AS CORP_ROWS FROM SCM_MGR.SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID = 'DMF0082';
